const dormir = (ms) => new Promise((r) => setTimeout(r, ms));
const cola = [];                 // la cola: un arreglo en la memoria
const hechos = [];

async function worker(nombre) {  // saca trabajos mientras haya
  while (cola.length > 0) {
    const job = cola.shift();    // se completa entero antes de que corra el otro worker
    await dormir(job.ms);        // el trabajo lento (simulado)
    hechos.push(`${nombre} hizo ${job.tipo} #${job.id}`);
  }
}

